<?php
session_start();require_once __DIR__.'/config/database.php';if(isset($_SESSION['user_id'])){header('Location:index.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$e=trim($_POST['email']??'');$p=$_POST['password']??'';$s=$conn->prepare("SELECT id,name,email,password,role FROM users WHERE email=? LIMIT 1");$s->bind_param("s",$e);$s->execute();$u=$s->get_result()->fetch_assoc();if($u&&$u['role']==='user'&&password_verify($p,$u['password'])){$c=$conn->prepare("SELECT id FROM clients WHERE user_id=? LIMIT 1");$c->bind_param("i",$u['id']);$c->execute();$cl=$c->get_result()->fetch_assoc();if($cl){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];$_SESSION['user_name']=$u['name'];$_SESSION['user_email']=$u['email'];$_SESSION['client_id']=$cl['id'];header('Location:index.php');exit;}else$error='Customer profile not found.';}else$error='Invalid email or password.';}?>
